    if (f.role === "CheckBox") continue;
    const lower = f.value.toLowerCase();
    if (lowerClaimed.includes(lower) || isChrome(f.value) || seen.has(lower)) continue;
    seen.add(lower);
    out.push(f.value);
  }
  return out;
};

