    { ...snapshot, url: undefined },
    PARSER_ID,
    threadKey(parts, ctx),
    title,
    undefined,
    { kind: "document", title, text: lines.join("\n") },
  );
  out.truncated = out.truncated || truncated;
  return out;
}
