// Terminal emulators (Terminal.app, Warp, iTerm2).
//
// A terminal exposes its whole scrollback as one text area. The parser learns one prompt
// shape from the first prompt-looking line, splits the buffer into commands and their output
// on that shape only, and keeps the newest segments within a character cap.

export const meta = {
  api: 1,
  kind: "parser",
  match: {
    bundleIds: ["com.apple.Terminal", "dev.warp.Warp-Stable", "dev.warp.Warp", "com.googlecode.iterm2"],
  },
};

// Rendered characters kept per capture. Oldest segments go first.
const CONTENT_CAP = 8000;

// A prompt terminator that may follow a path or `user@host path`.
const PROMPT_CHARS = ["%", "$", "#", ">", "❯"];
// Characters that end a path component run in a prompt or title.
const PATH_STOP_CHARS = [" ", "\t", "\n", ":", "%", "$", "#", ">", "❯"];

// Rust `char::is_whitespace` (Unicode White_Space), which differs from JS `\s`.
const isWs = (c) =>
  c === " " || (c >= "\t" && c <= "\r") || c === "\u0085" || c === " " || c === " " ||
  (c >= " " && c <= " ") || c === " " || c === " " || c === " " ||
  c === " " || c === "　";

const isAlnum = (c) => /^[\p{Alphabetic}\p{N}]$/u.test(c);

const chars = (s) => [...s];

// Rust `str::lines`: split on "\n", drop one trailing "\r" per terminated line, and no empty
// final line after a trailing "\n".
const rustLines = (s) => {
  const parts = s.split("\n");
  const last = parts.length - 1;
  if (parts[last] === "") parts.pop();
  return parts.map((p, i) => (i < last && p.endsWith("\r") ? p.slice(0, -1) : p));
};

// Terminal's own slug: trimmed, lowercased, spaces to dashes.
const slug = (s) => s.trim().toLowerCase().split(" ").join("-");

const isPromptChar = (c) => PROMPT_CHARS.includes(c);

// One command and what it printed. `command` is undefined for output before the first prompt
// and for a buffer whose prompt could not be learned.
const segmentLines = (seg) => {
  const out = [];
  if (seg.command !== undefined) out.push(`$ ${seg.command}`);
  const output = seg.output.replace(/\n+$/, "");
  if (output !== "") out.push(output);
  return out;
};
const segmentText = (seg) => segmentLines(seg).join("\n");

// Where a prompt of `shape` ends in `line` (an array of chars), if the line starts with one.
const promptHeadEnd = (line, shape) => {
  if (shape === "userHost") {
    // `^\S+@\S+\s`: the first word holds an `@` with text on both sides, then whitespace.
    const wordEnd = line.findIndex(isWs);
    if (wordEnd < 0) return undefined;
    let qualifies = false;
    for (let i = 0; i < wordEnd; i++) {
      if (line[i] === "@" && i > 0 && i + 1 < wordEnd) qualifies = true;
    }
    return qualifies ? wordEnd + 1 : undefined;
  }
  // `^[~/]\S* [%$❯](\s|$)`
  if (line[0] !== "~" && line[0] !== "/") return undefined;
  const wordEnd = line.findIndex(isWs);
  if (wordEnd < 0) return undefined;
  if (line[wordEnd] !== " ") return undefined;
  const terminator = line[wordEnd + 1];
  if (terminator === undefined) return undefined;
  if (terminator !== "%" && terminator !== "$" && terminator !== "❯") return undefined;
  const after = line[wordEnd + 2];
  if (after === undefined) return wordEnd + 2;
  if (isWs(after)) return wordEnd + 3;
  return undefined;
};

// The shape of the first line that looks like a prompt. Every later split uses that one
// shape, so a path printed by a command cannot start a segment.
const promptShape = (lines) => {
  for (const line of lines) {
    const cs = chars(line);
    for (const shape of ["userHost", "path"]) {
      if (promptHeadEnd(cs, shape) !== undefined) return shape;
    }
  }
  return undefined;
};

const trimBlanks = (s) => s.replace(/^[ \t]+/, "").replace(/[ \t]+$/, "");

// What the user typed on a prompt line: empty for an idle prompt, undefined for an output line.
const commandText = (line, shape) => {
  const cs = chars(line);
  const head = promptHeadEnd(cs, shape);
  if (head === undefined) return undefined;
  let rest = cs.slice(Math.min(head, cs.length));
  if (shape === "userHost") {
    // Only `user@host ` was consumed. The cwd and the terminator follow it. The path
    // shape already consumed its terminator, so it must not be stripped twice.
    for (let i = 0; i < rest.length; i++) {
      if (isPromptChar(rest[i]) && (i + 1 >= rest.length || isWs(rest[i + 1]))) {
        rest = rest.slice(Math.min(i + 2, rest.length));
        break;
      }
    }
  }
  return trimBlanks(rest.join(""));
};

// Splits a scrollback blob into segments on the learned prompt shape.
const segments = (blob) => {
  const lines = blob.split("\n");
  const shape = promptShape(lines);
  if (shape === undefined) {
    // A full-screen program, a pager or an unknown prompt theme.
    return [{ command: undefined, output: blob, running: false }];
  }
  const out = [];
  let preamble = [];
  let open = null; // { command, output: [] }

  const flush = (running) => {
    if (open !== null) {
      out.push({ command: open.command, output: open.output.join("\n"), running });
      open = null;
    } else if (preamble.length > 0) {
      out.push({ command: undefined, output: preamble.join("\n"), running: false });
      preamble = [];
    }
  };

  for (const line of lines) {
    const command = commandText(line, shape);
    if (command === undefined) {
      if (open !== null) open.output.push(line);
      else preamble.push(line);
      continue;
    }
    flush(false);
    // An idle prompt closes the previous segment and opens nothing.
    open = command !== "" ? { command, output: [] } : null;
  }
  // Still open at the end means no trailing prompt, so the command has not returned.
  flush(open !== null);
  return out;
};

// The first `~` or `/Users/<name>` path at or after `from`, with its trailing components.
// Returns char indices [start, end] of the match.
const USERS = chars("/Users/");
const findPath = (cs, from) => {
  const allowed = (c) => !PATH_STOP_CHARS.includes(c);
  for (let start = from; start < cs.length; start++) {
    let end;
    if (cs[start] === "~") {
      end = start + 1;
    } else if (USERS.every((c, k) => cs[start + k] === c)) {
      const nameStart = start + 7;
      let nameLen = 0;
      while (nameStart + nameLen < cs.length && cs[nameStart + nameLen] !== "/" && cs[nameStart + nameLen] !== " ") {
        nameLen += 1;
      }
      if (nameLen === 0) continue;
      end = nameStart + nameLen;
    } else {
      continue;
    }
    // `(/[^ \t\n:%$#>❯]+)*`
    while (cs[end] === "/" && cs[end + 1] !== undefined && allowed(cs[end + 1])) {
      end += 1;
      while (cs[end] !== undefined && allowed(cs[end])) end += 1;
    }
    return [start, end];
  }
  return undefined;
};

// The full cwd path, read from the window title only. Prompt text is untrusted captured
// content and does not decide the session's directory.
const cwdPath = (windowTitle) => {
  if (windowTitle === undefined || windowTitle === null) return undefined;
  const title = chars(windowTitle);
  const found = findPath(title, 0);
  if (found === undefined) return undefined;
  return title.slice(found[0], found[1]).join("");
};

// The final component of a `~/...` or `/Users/...` path, slugged. With `requirePrompt` the
// path must be followed by a prompt terminator, so file arguments and paths in output are not
// mistaken for the shell's directory.
const lastPathComponent = (s, requirePrompt) => {
  const cs = chars(s);
  let from = 0;
  let start;
  let end;
  for (;;) {
    const found = findPath(cs, from);
    if (found === undefined) return undefined;
    [start, end] = found;
    if (!requirePrompt) break;
    const after = cs.slice(end).find((c) => !isWs(c));
    if (after !== undefined && isPromptChar(after)) break;
    from = start + 1;
  }
  const path = cs.slice(start, end).join("");
  const last = path.split("/").reverse().find((c) => c !== "");
  if (last === undefined) return undefined;
  // A real cwd rarely looks like a file name.
  const lc = chars(last);
  const dot = lc.lastIndexOf(".");
  if (dot > 0) {
    const ext = lc.slice(dot + 1);
    if (ext.length <= 5 && ext.every(isAlnum)) return undefined;
  }
  return slug(last);
};

// The thread key: the app plus the directory of the most recent prompt, else of the
// window title, else the bare app. Titles of full-screen programs change on every read,
// so they are never used as a key.
const threadKey = (appName, scrollbackText, windowTitle) => {
  const app = slug(appName);
  let dir;
  const lines = rustLines(scrollbackText);
  for (let i = lines.length - 1; i >= 0; i--) {
    dir = lastPathComponent(lines[i], true);
    if (dir !== undefined) break;
  }
  if (dir === undefined && windowTitle !== undefined && windowTitle !== null) {
    dir = lastPathComponent(windowTitle, false);
  }
  return dir !== undefined ? `terminal:${app}/${dir}` : `terminal:${app}`;
};

// The scrollback: the longest non-empty text area. Small text areas are search boxes.
const scrollback = (snapshot, ctx) => {
  let best;
  let bestLen = 0;
  for (const node of ctx.findAll("//TextArea", snapshot.root)) {
    if (ctx.node.isSecure(node)) continue;
    const v = node.value;
    if (v === undefined || v === null || v === "") continue;
    const len = chars(v).length;
    if (best === undefined || len > bestLen) {
      best = v;
      bestLen = len;
    }
  }
  return best;
};

// Drops the oldest segments until the text fits `cap`, keeping at least one. A single
// segment that is still too long keeps its tail. Returns the text and whether it was cut.
const bound = (segs, cap) => {
  const cost = (s) => chars(segmentText(s)).length + 1;
  let total = Math.max(0, segs.reduce((n, s) => n + cost(s), 0) - 1);
  let cut = false;
  while (segs.length > 1 && total > cap) {
    total = Math.max(0, total - cost(segs.shift()));
    cut = true;
  }
  let text = segs.map(segmentText).filter((t) => t !== "").join("\n");
  const cs = chars(text);
  if (cs.length > cap) {
    text = cs.slice(cs.length - cap).join("");
    cut = true;
  }
  return [text, cut];
};

export function parse(snapshot, ctx) {
  const blob = scrollback(snapshot, ctx);
  if (blob === undefined) return null;
  const title = snapshot.window_title;
  const [text, truncated] = bound(segments(blob), CONTENT_CAP);
  const docTitle = cwdPath(title) ?? title ?? "";
  const out = ctx.item(
    snapshot,
    "terminal/v1",
    threadKey(snapshot.app.name, blob, title),
    docTitle === "" ? snapshot.app.name : docTitle,
    undefined,
    { kind: "document", title: docTitle, text },
  );
  // Terminal items never carry a URL.
  delete out.url;
  out.truncated = truncated;
  return out;
}
"""#),
        ("viber", #"""
// Viber for macOS (Qt Quick). Its accessibility tree has the open chat's messages as text
// fields, but never the chat's name: the header is drawn without an accessible element, the
// window title is always "Rakuten Viber" and the chat list is not exposed at all. So this rule
// asks lookback to read the header strip from the screen (`ocrRegions`) and keys the thread by
// the name read there. Without the Screen Recording permission there is no name, and the
// generic rule stores the window as before.
//
// Shape (identifiers are QML type paths; only their stable parts are matched):
//   Group  …StackView_QMLTYPE…                the open chat, header at its top
//     Button …SearchButton… / …InfoButton…    header buttons, right of the chat name
//     TextField …FeedDelegate…TextEditItem…   one per message; the user's own sit right
//     TextField …QQuickTextEdit…              the composer
export const meta = {
  api: 1,
  kind: "parser",
  match: { bundleIds: ["com.viber.osx"] },
};

const PARSER_ID = "viber/v1";
const PANE = `//Group[identifier*="StackView_QMLTYPE"]`;
const MESSAGE = "TextEditItem_QMLTYPE";
const COMPOSER = "QQuickTextEdit";
// The header strip under the pane's top edge: avatar, then the name and a subtitle line.
const HEADER_HEIGHT = 84;
const AVATAR_WIDTH = 80;
// A group's subtitle lists members ("Ana, Bo, Cy") or counts them ("12 members"). A direct
// chat's is a phone number or a presence line ("Last seen yesterday at 20:49", "Online").
const GROUP_SUBTITLE = /, |\b\d+\s+(members|participants)\b/i;

const clean = (s) =>
  typeof s === "string" ? s.replace(/[‎‏‪-‮⁦-⁩]/g, "").trim() : "";

function pane(root, ctx) {
  return ctx.find(PANE, root);
}

// The left edge of the header buttons (search, call, info), or the pane's right edge.
function headerRight(p) {
  const top = p.frame.y + HEADER_HEIGHT;
  let right = p.frame.x + p.frame.width;
  for (const c of p.children ?? []) {
    const f = c.frame;
    if (!f || f.y >= top) continue;
    if (c.role === "Button" || c.role === "CheckBox") right = Math.min(right, f.x);
  }
  return right;
}

export function ocrRegions(snapshot, ctx) {
  const p = pane(snapshot.root, ctx);
  if (!p || !p.frame) return [];
  const x = p.frame.x + AVATAR_WIDTH;
  const width = headerRight(p) - 8 - x;
  if (width < 40) return [];
  return [{ name: "header", x, y: p.frame.y, width, height: HEADER_HEIGHT }];
}

export function parse(snapshot, ctx) {
  const lines = (snapshot.ocr?.header ?? []).map(clean).filter((l) => l.length > 1);
  const chat = lines[0] ?? "";
  if (chat === "") return null;
  const subtitle = lines[1] ?? "";
  const direct = !GROUP_SUBTITLE.test(subtitle);

  const root = snapshot.root;
  const p = pane(root, ctx) ?? root;
  const middle = p.frame ? p.frame.x + p.frame.width / 2 : undefined;
  const bubbles = ctx.sortedByVisualOrder(
    ctx.findAll(`//TextField[identifier*="${MESSAGE}"]`, p),
    p.frame,
  );
  const messages = [];
  for (const b of bubbles) {
    if (ctx.node.isSecure(b)) continue;
    const text = clean(ctx.textOf(b));
    if (text === "") continue;
    const f = b.frame;
    const isMe = middle !== undefined && f ? f.x + f.width / 2 > middle : false;
    const m = { text, is_me: isMe, draft: false };
    // A group's bubbles do not say who wrote them; a direct chat's are the other person's.
    if (isMe) m.author = "You";
    else if (direct) m.author = chat;
    messages.push(m);
  }
  const composer = ctx.find(`//TextField[identifier*="${COMPOSER}"]`, p);
  const draft = composer ? ctx.draft(composer) : undefined;
  if (draft !== undefined) messages.push(draft);
  if (messages.length === 0) return { refuse: "no-messages" };

  const content = { kind: "conversation", title: chat, is_group: !direct, messages };
  return ctx.item(snapshot, PARSER_ID, `viber:${ctx.slug(chat)}`, chat, undefined, content);
}
"""#),
        ("whatsapp", #"""
// WhatsApp for macOS (the Catalyst app). The open chat's name is the label of
// `NavigationBar_HeaderViewButton`, and every message is a `WAMessageBubbleTableViewCell`
// whose label reads like VoiceOver:
//
//   message, <text>, <time>, Received from <name>
//   Your message, <text>, <time>, Sent to <name>, Read
//   Message from <sender>, <text>, <time>, Received in <group>
//   Replying to <name>.\n<one of the above>.\nQuoted message.\n<quoted text>
//
// Calls, photos and other non-text bubbles have no "message" prefix; their whole lead is kept
// as the text ("Photo", "Missed voice call"). Labels carry U+200E marks, which are dropped.
//
// Older builds name the chat in a heading labelled "conversation title" and give each bubble
// either a "Name: text" label or its text and time as child texts. There the side of the
// window a bubble sits on tells the user's own messages apart.
export const meta = {
  api: 1,
  kind: "parser",
  match: { bundleIds: ["net.whatsapp.WhatsApp"] },
};

const PARSER_ID = "whatsapp/v1";
const HEADER = "NavigationBar_HeaderViewButton";
const MESSAGES = "ChatMessagesTableView";
const BUBBLE = "WAMessageBubbleTableViewCell";
const COMPOSER = "ChatBar_ComposerTextView";
const MESSAGES_PREFIX = "Messages in chat with ";
const LEGACY_TITLE_LABEL = "conversation title";
// "16:02" or "4:02 PM", the trailing child text of a legacy bubble.
const LEGACY_TIME = /^\d{1,2}:\d{2}(\s?[AP]M)?$/i;
// The VoiceOver-style label of current builds.
const VOICEOVER = /^(Replying to |Your message, |message, |Message from )|, (Received from|Received in|Sent to) /;

// Direction marks, bidi embeddings and isolates that WhatsApp wraps names and labels in.
const clean = (s) =>
  typeof s === "string" ? s.replace(/[‎‏‪-‮⁦-⁩]/g, "").trim() : "";

// "13:43", "7:05 PM", "25. October at 12:10", "October 25 at 12:10 PM", "Yesterday at 9:00".
const TIME_TAIL = /, ((?:[^,]* at )?\d{1,2}[:.]\d{2}(?:\s?[AP]M)?)$/i;

// The direction marker that ends the message part of a bubble label.
const DIRECTION = /, (Received from|Received in|Sent to) ([^,]*)(?:, .*)?$/;

function parseBubble(raw, chat) {
  let text = clean(raw);
  if (text === "") return undefined;
  // A reply quotes the original after the message; keep the reply itself.
  let lines = text.split("\n").map(clean);
  if (lines[0].startsWith("Replying to ")) lines = lines.slice(1);
  let main = lines[0] ?? "";
  if (main.endsWith(".")) main = main.slice(0, -1);

  let direction;
  let peer;
  const d = main.match(DIRECTION);
  if (d) {
    direction = d[1];
    peer = clean(d[2]);
    main = main.slice(0, d.index);
  }
  let sentAt;
  const t = main.match(TIME_TAIL);
  if (t) {
    sentAt = t[1];
    main = main.slice(0, t.index);
  }

  let isMe = direction === "Sent to";
  let author;
  if (main.startsWith("Your message, ")) {
    isMe = true;
    main = main.slice("Your message, ".length);
  } else if (main.startsWith("Message from ")) {
    // Group chats: "Message from <sender>, <text>".
    const rest = main.slice("Message from ".length);
    const comma = rest.indexOf(", ");
    if (comma > 0) {
      author = clean(rest.slice(0, comma));
      main = rest.slice(comma + 2);
    }
  } else if (main.startsWith("message, ")) {
    main = main.slice("message, ".length);
  }
  if (isMe) author = "You";
  else if (author === undefined && direction === "Received from") author = peer || chat;

  main = clean(main);
  if (main === "") return undefined;
  const m = { text: main, is_me: isMe, draft: false };
  if (author !== undefined && author !== "") m.author = author;
  if (sentAt !== undefined) m.sent_at = sentAt;
  return m;
}

// A bubble from an older build: "Name: text" in the label, or the text and its time as child
// texts. `rightSide` marks the user's own bubbles there.
function parseLegacyBubble(cell, chat, rightSide, ctx) {
  const label = clean(ctx.node.label(cell));
  const colon = label.indexOf(": ");
  if (colon > 0) {
    const sender = label.slice(0, colon).trim();
    const text = label.slice(colon + 2).trim();
    if (text === "") return undefined;
    const isMe = sender === "You";
    return { author: isMe ? "You" : sender, text, is_me: isMe, draft: false };
  }
  const texts = ctx.staticTextsExcluding(cell, () => false).map(clean).filter((t) => t !== "");
  let sentAt;
  if (texts.length > 1 && LEGACY_TIME.test(texts[texts.length - 1])) sentAt = texts.pop();
  const text = texts.length > 0 ? texts.join(" ") : label;
  if (text === "") return undefined;
  const m = { author: rightSide ? "You" : chat, text, is_me: rightSide, draft: false };
  if (sentAt !== undefined) m.sent_at = sentAt;
  return m;
}

function isRightSide(cell, root) {
  const f = cell.frame;
  const w = root.frame;
  if (!f || !w || !(w.width > 0)) return false;
  return f.x + f.width / 2 > w.x + w.width / 2;
}

// The header button's label is the chat name. Its value is a subtitle: "Members: Ana, Bo …"
// in a group, so it must not win over the label the way `ctx.textOf` would let it.
function chatName(root, ctx) {
  const header = ctx.find(`//*[identifier="${HEADER}"]`, root);
  const name = header ? clean(ctx.node.label(header)) || clean(header.name) : "";
  if (name !== "") return name;
  const list = ctx.find(`//*[identifier="${MESSAGES}"]`, root);
  const label = list ? clean(ctx.node.label(list)) : "";
  if (label.startsWith(MESSAGES_PREFIX)) return label.slice(MESSAGES_PREFIX.length).trim();
  const subtitle = header ? clean(header.value) : "";
  if (subtitle !== "" && !subtitle.startsWith("Members:")) return subtitle;
  const legacy = ctx.find(`//Heading[label="${LEGACY_TITLE_LABEL}"]`, root);
  return legacy ? clean(ctx.textOf(legacy)) : "";
}

export function parse(snapshot, ctx) {
  const root = snapshot.root;
  const chat = chatName(root, ctx);
  if (chat === "") {
    // Messages with no chat to file them under: the header is not there yet, mid-switch.
    // Generic would store the chat list of every unopened chat instead, so store nothing.
    if (ctx.find(`//*[identifier="${BUBBLE}"]`, root)) return { refuse: "unconfirmed-chat" };
    // No open chat (Updates, Calls, settings): let the generic rule have it.
    return null;
  }

  const list = ctx.find(`//*[identifier="${MESSAGES}"]`, root) ?? root;
  const bubbles = ctx.sortedByVisualOrder(ctx.findAll(`//*[identifier="${BUBBLE}"]`, list), list.frame);
  const messages = [];
  for (const b of bubbles) {
    if (ctx.node.isSecure(b)) continue;
    const label = clean(ctx.node.label(b));
    const m = VOICEOVER.test(label)
      ? parseBubble(label, chat)
      : parseLegacyBubble(b, chat, isRightSide(b, root), ctx);
    if (m !== undefined) messages.push(m);
  }
  const composer = ctx.find(`//*[identifier="${COMPOSER}"]`, root);
  const draft = composer ? ctx.draft(composer) : undefined;
  if (draft !== undefined) messages.push(draft);
  if (messages.length === 0) return null;

  // A group bubble names its sender; a 1:1 chat never does.
  const isGroup = messages.some((m) => !m.is_me && m.author !== undefined && m.author !== chat);
  const content = { kind: "conversation", title: chat, is_group: isGroup, messages };
  return ctx.item(snapshot, PARSER_ID, `whatsapp:${ctx.slug(chat)}`, chat, undefined, content);
}
"""#),
    ]
}
